const form = $('Drop LinkedIn URL').first().json;
const url = String(form['LinkedIn URL'] || form.linkedin_url || '').trim();
const raw = $input.first().json;
let html = '';
if (typeof raw === 'string') html = raw;
else if (raw && typeof raw.data === 'string') html = raw.data;
else html = String(raw.body || raw.data || '');
function pick(prop, name) {
  const a = html.match(new RegExp('property=["\']' + prop + '["\']\\s+content=["\']([^"\']*)["\']', 'i'));
  if (a) return a[1];
  const b = html.match(new RegExp('content=["\']([^"\']*)["\']\\s+property=["\']' + prop + '["\']', 'i'));
  if (b) return b[1];
  if (name) {
    const c = html.match(new RegExp('name=["\']' + name + '["\']\\s+content=["\']([^"\']*)["\']', 'i'));
    if (c) return c[1];
  }
  return '';
}
function decode(s) {
  return String(s || '')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\u2014/g, ', ')
    .replace(/\u2013/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}
const title = decode(pick('og:title'));
const text = decode(pick('og:description', 'description'));
if (!url || text.length < 40) {
  throw new Error('LinkedIn did not give enough public text. Open the post, copy the body, and try a post that is public.');
}
return [{ json: { url, title: title || 'LinkedIn-Beitrag', text } }];

const post = $('Read public post').first().json;
const ingest = $input.first().json;
const id = ingest.id || (ingest.task && ingest.task.id);
if (!id) throw new Error('WordPress ingest did not return an id.');
const titleDe = String(post.title || '').slice(0, 140);
const excerptDe = String(post.text || '').slice(0, 420);
return [{ json: {
  id,
  agent: 'analyst',
  result: 'done',
  payload: {
    title_de: titleDe,
    excerpt_de: excerptDe,
    byline_de: 'Eurasien-Gesellschaft',
    title_en: 'TEST EN: ' + titleDe,
    excerpt_en: 'Test English card from a dry run. Source: the LinkedIn post. Nothing was published to the live Analysen page.',
    byline_en: 'Eurasien Gesellschaft'
  }
} }];

const id = $('Analyst (test stub)').first().json.id;
const ingest = $('WP ingest').first().json;
return [{ json: {
  ok: true,
  id,
  duplicate: !!ingest.duplicate,
  stage: (ingest.task && ingest.task.stage) || 'preview',
  sandbox: 'https://eurasiengesellschaft.de/app/eg-editorial-sandbox.php?id=' + id,
  note: 'Test run finished. Open the sandbox. The live Analysen page was not changed.'
} }];
